SELECT * FROM brick_endpoint_definition
WHERE swagger_mapping_id = #{swaggerMappingId}
  AND http_method = #{httpMethod}
  AND endpoint_path = #{endpointPath}
  AND host = #{host}
  AND base_path = #{basePath}
  AND is_deleted = #{isDeleted}
LIMIT 1

SELECT * FROM brick_endpoint_definition
WHERE swagger_mapping_id = #{swaggerMappingId} AND is_deleted = #{isDeleted}
AND http_method = #{httpMethod}
AND (endpoint_path LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY update_time DESC
LIMIT #{offset}, #{pageSize}

SELECT swagger_mapping_id, COUNT(*) as total, SUM(CASE WHEN is_lightweight = 0 THEN 1 ELSE 0 END) as non_lightweight, http_method, MAX(update_time) as latest_update_time FROM brick_endpoint_definition WHERE swagger_mapping_id IN
#{id}
AND is_deleted = #{isDeleted}
AND (endpoint_path LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY swagger_mapping_id, http_method

SELECT swagger_mapping_id, MAX(update_time) as latest_update_time
FROM brick_endpoint_definition
WHERE swagger_mapping_id IN

    #{id}

AND is_deleted = #{isDeleted}
GROUP BY swagger_mapping_id

SELECT COUNT(DISTINCT endpoint_id)
FROM brick_flow_node
WHERE endpoint_id IN (
    SELECT id FROM brick_endpoint_definition WHERE swagger_mapping_id = #{swaggerMappingId}
)
AND is_deleted = 0
